  for (const c of candidates) {
    if (c !== undefined && c !== null && c !== '') return c;
  }
  return null;
}
function extractMetricFromDescription(desc) {
  if (!desc) return null;
  if (/bigquery/i.test(desc))       return 'BigQuery';
  if (/cloud.?run/i.test(desc))     return 'Cloud_Run';
  if (/cpu|processor/i.test(desc))  return 'CPU';
  if (/mem/i.test(desc))            return 'Memory';
  if (/disk|storage/i.test(desc))   return 'Storage';
  if (/net/i.test(desc))            return 'Network';
  if (/sec|auth/i.test(desc))       return 'Security';
  if (/app|error|http/i.test(desc)) return 'Application';
  return pick(src.type, 'Application');
}
function extractSeverityFromDescription(desc) {
  if (!desc) return null;
  if (/critical/i.test(desc))   return 'critical';
  if (/major|high/i.test(desc)) return 'high';
  if (/minor|med/i.test(desc))  return 'medium';
  if (/warn/i.test(desc))       return 'low';
  return null;
}
function derivePlatformType(s) {
  const metric  = String(s.metric_name        || '').toLowerCase().trim();
  const ci      = String(s.cmdb_ci            || '').toLowerCase().trim();
  const service = String(s.cloud_run_service  || '').toLowerCase().trim();
  if (metric === 'bigquery'  || ci.includes('bigquery'))  return 'bigquery';
  if (metric === 'cloud_run' || metric === 'cloudrun'
      || service.length > 0)                              return 'cloud_run';
  return 'compute_engine';
}
