  environment      : pick(src.environment, src.u_environment, src.env, src.u_environment_name),
  assignment_group : pick(src.assignment_group, src.u_assignment_group, src.assignmentGroup),
  cmdb_ci          : pick(src.cmdb_ci, src.u_cmdb_ci, src.ci, src.configuration_item),
  node             : pick(src.node, src.host, src.hostname, src.resource, src.instance_id, src.cmdb_ci, src.configuration_item),
  metric_name      : metric_name,
  severity         : pick(src.severity, src.u_severity, src.priority,
                          extractSeverityFromDescription(description), 'medium'),
  service_platform : pick(src.service_platform, src.u_platform, src.platform),
  gmom_event_id    : pick(src.gmom_event_id, src.u_gmom_event_id, src.u_gmom_event_ids, src.event_id),
  current_value    : pick(src.current_value, src.value, null),
  description      : description,
  alert_source     : pick(src.source, 'webhook'),
  platform_type    : pick(src.platform_type, derivePlatformType(src)),
  raw_payload      : body,
  received_at      : new Date().toISOString(),
  source           : 'webhook'
};
return canonical;

function extractLine(text, label) { const rx = new RegExp(label + '\\s*:?\\s*([^\\n]+)', 'i'); const m = text.match(rx); return m ? m[1].trim() : null; }
function extractSection(text, label, stopLabels) {
  const stopPattern = stopLabels.join('|');
  const rx = new RegExp(label + '\\s*:?\\s*([\\s\\S]*?)(?=\\n(?:' + stopPattern + ')|$)', 'i');
  const m = text.match(rx); return m ? m[1].trim().replace(/\s+/g, ' ') : null;
}
const STOP_LABELS = ['IMMEDIATE ACTION', 'SHORT-TERM FIX', 'LONG-TERM', 'ESCALATE TO L2'];
function itemSafe(nodeName) {
  try { return $(nodeName).item.json; } catch (e) {
    try { return $(nodeName).first().json; } catch (e2) { return {}; }
  }
}
function summarizeAgent(agentNodeName, sshNodeName) {
  let agentText = '', sshFailed = true;
  try { const j = itemSafe(agentNodeName); agentText = j.output || j.text || ''; } catch (e) { agentText = ''; }
  try { sshFailed = !!itemSafe(sshNodeName).error; } catch (e) { sshFailed = true; }
  return {
    pinpointed_cause: extractLine(agentText, 'PINPOINTED CAUSE') || 'See full analysis for details',
    recommendation: extractLine(agentText, 'SHORT-TERM FIX') || extractLine(agentText, 'IMMEDIATE ACTION') || 'See full analysis for recommendation',
    analysis_summary: extractSection(agentText, 'OBSERVED CONDITION', STOP_LABELS) || 'See full analysis for details',
    agent_full_analysis: agentText,
    diagnostic_available: !sshFailed
  };
}
const domainReports = {
  CPU: summarizeAgent('CPU Agent', 'SSH: CPU Diagnostics'),
  Memory: summarizeAgent('MEMORY Agent', 'SSH: MEMORY Diagnostics'),
  Storage: summarizeAgent('STORAGE Agent', 'SSH: STORAGE Diagnostics'),
  Network: summarizeAgent('NETWORK Agent', 'SSH: NETWORK Diagnostics'),
  Security: summarizeAgent('SECURITY Agent', 'SSH: SECURITY Diagnostics'),
  Application: summarizeAgent('APPLICATION Agent', 'SSH: APPLICATION Diagnostics')
};
const alert = itemSafe('Resource Enrichment Lookup');
function inferDomain(metricName, description) {
  const src = ((metricName || '') + ' ' + (description || '')).toLowerCase();
  if (/cpu|processor|utiliz/i.test(src)) return 'CPU';
  if (/mem|memory|swap/i.test(src)) return 'Memory';
  if (/disk|storage|filesystem|space/i.test(src)) return 'Storage';
  if (/net|network|tcp|http|connect/i.test(src)) return 'Network';
  if (/sec|auth|access|denied|login/i.test(src)) return 'Security';
  return 'Application';
}
