return [{ json: {
  ...alert,
  pinpointed_cause: matched.pinpointed_cause,
  recommendation: matched.recommendation,
  analysis_summary: matched.analysis_summary,
  agent_full_analysis: matched.agent_full_analysis,
  diagnostic_available: matched.diagnostic_available,
  full_system_report: fullSystemReport,
  agents_run: Object.keys(domainReports).length
} }];

