const cmdb_ci_key          = (alert.cmdb_ci         || '').toLowerCase().trim();
const assignment_group_key = (alert.assignment_group || '').toLowerCase().trim();
const metric_key           = (alert.metric_name      || '').toLowerCase().trim();

let enrichment = null;
let lookup_key = null;

for (const [key, value] of Object.entries(RESOURCE_MAP)) {
  if (key.toLowerCase() === cmdb_ci_key) {
    enrichment = value;
    lookup_key = key;
    break;
  }
}

if (!enrichment) {
  for (const [key, value] of Object.entries(RESOURCE_MAP)) {
    if (key.toLowerCase() === assignment_group_key) {
      enrichment = value;
      lookup_key = key;
      break;
    }
  }
}

if (enrichment) {
  if (metric_key === 'bigquery' && enrichment.platform_type !== 'bigquery') {
    enrichment = {
      ...enrichment,
      platform_type    : 'bigquery',
      bigquery_dataset : enrichment.bigquery_dataset || cmdb_ci_key || 'unknown'
    };
  }
  if ((metric_key === 'cloud_run' || metric_key === 'cloudrun')
      && enrichment.platform_type !== 'cloud_run') {
    enrichment = {
      ...enrichment,
      platform_type     : 'cloud_run',
      cloud_run_service : enrichment.cloud_run_service || cmdb_ci_key || 'unknown'
    };
  }
}

if (!enrichment) {
  return {
    json: {
      ...alert,
      enrichment_found                   : false,
      _lookup_key                        : null,
      _lookup_attempted_cmdb_ci          : cmdb_ci_key,
      _lookup_attempted_assignment_group : assignment_group_key
    }
  };
}

return {
  json: {
    ...alert,
    ...enrichment,
    enrichment_found : true,
    _lookup_key      : lookup_key
  }
};

// ============================================================
// NODE: Log Auto-Acknowledgment
// PURPOSE: Agent self-acknowledges the L1 alert immediately
// after notifying xMatters -- no human needed for ack.
// ============================================================
const a = $json;
const staticData = $getWorkflowStaticData('global');
if (staticData.detailStore?.[a.alert_number]) {
  staticData.detailStore[a.alert_number].l1_status      = 'Auto-Acknowledged';
  staticData.detailStore[a.alert_number].acknowledged_at = new Date().toISOString();
  staticData.detailStore[a.alert_number].acknowledged_by = 'L1 AI Triage Agent';
}
return {
  json: {
    ...a,
    l1_status        : 'Auto-Acknowledged',
    acknowledged_by  : 'L1 AI Triage Agent',
    acknowledged_at  : new Date().toISOString()
  }
};

// ============================================================
// NODE: Dead Letter Log
// PURPOSE: Operational visibility when diagnostics failed.
// ============================================================
const a = $json;
if (a.diagnostic_available === false) {
  const staticData = $getWorkflowStaticData('global');
  if (!staticData.deadLetterLog) staticData.deadLetterLog = [];
  staticData.deadLetterLog.push({
    alert_number : a.alert_number,
    metric_name  : a.metric_name,
    node         : a.node,
    environment  : a.environment,
    severity     : a.severity,
    reason       : 'diagnostic_available=false -- SSH/API call to the resource likely failed',
    logged_at    : new Date().toISOString()
  });
  if (staticData.deadLetterLog.length > 500) {
    staticData.deadLetterLog = staticData.deadLetterLog.slice(-500);
  }
}
return { json: a };

// ============================================================
// NODE: Dedup Check
// PURPOSE: Suppress duplicate alerts within dedup window.
// Override window with $vars.DEDUP_WINDOW_MINUTES (default 30).
// ============================================================
const a = $json;
const dedupWindowMinutes = Number($vars.DEDUP_WINDOW_MINUTES) || 30;
const key = `${(a.cmdb_ci || 'unknown').toLowerCase()}::${(a.metric_name || 'unknown').toLowerCase()}::${(a.environment || 'unknown').toLowerCase()}`;
const staticData = $getWorkflowStaticData('global');
if (!staticData.inFlightAlerts) staticData.inFlightAlerts = {};
const now = Date.now();
const existing = staticData.inFlightAlerts[key];
const windowMs = dedupWindowMinutes * 60 * 1000;
let is_duplicate = false;
let duplicate_of = null;
if (existing && (now - existing.since) < windowMs) {
  is_duplicate = true;
  duplicate_of = existing.alert_number;
} else {
  staticData.inFlightAlerts[key] = { since: now, alert_number: a.alert_number };
}
return {
  json: {
    ...a,
    is_duplicate_alert : is_duplicate,
    duplicate_of_alert : duplicate_of,
    dedup_key          : key
  }
};

// ============================================================
// NODE: Check API Key (webhook authentication)
// PURPOSE: Shared-secret check on inbound alert webhook.
// Set $vars.ALERT_INTAKE_API_KEY in n8n Settings -> Variables.
// Callers must send the key in the 'x-api-key' header.
// If variable is not set, all requests pass (backward-compatible).
// ============================================================
const expectedKey = $vars.ALERT_INTAKE_API_KEY;
const providedKey = $json.headers?.['x-api-key'];
const auth_configured = !!expectedKey;
const auth_passed = !auth_configured || providedKey === expectedKey;
return {
  json: {
    ...$json,
    auth_configured,
    auth_passed
  }
};

// ============================================================
// NODE: Validate Alert Payload
// PURPOSE: Reject malformed alerts early (400).
// ============================================================
const a = $json;
const errors = [];
if (!a.cmdb_ci && !a.assignment_group) errors.push('cmdb_ci or assignment_group is required');
if (!a.metric_name) errors.push('metric_name could not be determined');
if (!a.severity) errors.push('severity could not be determined');
if (!a.alert_number) errors.push('alert_number could not be generated');
return {
  json: {
    ...a,
    validation_passed : errors.length === 0,
    validation_errors : errors
  }
};
